MultiLanguageSpellData['en'][414564] = {name = "[q4]Cursed Cloth", additional_info = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Felcloth (20), Essence of Undeath (6), Dark Rune (2), Frozen Rune\n[q]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\n[q4]Cursed Cloth\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Mage, Priest, or Warlock who is willing to acquire the necessary reagents."}
MultiLanguageSpellData['en'][414565] = {name = "[q4]Languished Leather", additional_info = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune\n[q]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\n[q4]Languished Leather\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Druid or Rogue who is willing to acquire the necessary reagents."}
MultiLanguageSpellData['en'][414566] = {name = "[q4]Scourged Scales", additional_info = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune\n[q]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\n[q4]Scourged Scales\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Hunter or Shaman who is willing to acquire the necessary reagents."}
MultiLanguageSpellData['en'][414567] = {name = "[q4]Undeath Metal", additional_info = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Arcanite Bar (10), Essence of Undeath (6), Dark Rune (2), Frozen Rune\n[q]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\n[q4]Undeath Metal\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Paladin or Warrior who is willing to acquire the necessary reagents."}
