MultiLanguageSpellData['en'][429634] = {name = "Colossal Might", additional_info = "[q]Arms\n Colossal Might increases damage dealt by your next Demolish by 10%, stacking up to 5 times.\n\n Mortal Strike grants a stack of Colossal Might and Cleave grants a stack of Colossal Might when it strikes 3 or more targets.\n\nProtection\n Colossal Might increases damage dealt by your next Demolish by 10%, stacking up to 5 times.\n\n Shield Slam grants a stack of Colossal Might and Revenge grants a stack of Colossal Might when it strikes 3 or more targets."}
MultiLanguageSpellData['en'][429635] = {name = "Shadow of the Colossus", additional_info = "[q]Your Colossal Might intimidates your enemies, increasing your critical strike and critical block chance by 1% per stack for 6 sec against enemies affected by your Juggernaut Crash."}
MultiLanguageSpellData['en'][429636] = {name = "Dominance of the Colossus", additional_info = "[q]Arms\n Colossal Might now stacks up to 10 times. If you would gain a stack of Colossal Might and are at max stacks, the cooldown of Demolish is reduced by 2 sec.\n\n Enemies affected by Demolish take up to 10% more damage from you and deal up to 10% less damage to you for 10 sec based on the number of stacks of Colossal Might consumed by Demolish.\n\nProtection\n Colossal Might now stacks up to 10 times. If you would gain a stack of Colossal Might and are at max stacks, the cooldown of Demolish is reduced by 4 sec.\n\n Enemies affected by Demolish take up to 20% more damage from you and deal up to 10% less damage to you for 10 sec based on the number of stacks of Colossal Might consumed by Demolish."}
MultiLanguageSpellData['en'][429637] = {name = "One Against Many", additional_info = "[q]Arms\n Shockwave, Cleave, and Whirlwind deal 5% more damage per target affected up to 5.\n\nProtection\n Shockwave, Revenge, and Whirlwind deal 3% more damage per target affected up to 5."}
MultiLanguageSpellData['en'][429638] = {name = "Martial Expert", additional_info = "[q]Critical strike damage of your abilities is increased by 10% and the amount of damage blocked by your critical blocks is increased by 20%."}
MultiLanguageSpellData['en'][429639] = {name = "Boneshaker", additional_info = "[q]Shockwave's stun duration is increased by 1 sec and reduces the movement speed of affected enemies by 40% for 3 sec after the stun ends."}
MultiLanguageSpellData['en'][429641] = {name = "Tide of Battle", additional_info = "[q]Arms\n Colossal Might increases the damage of your Overpower by 5% per stack.\n\nProtection\n Colossal Might increases the damage of your Revenge by 7% per stack."}
MultiLanguageSpellData['en'][429642] = {name = "Mountain of Muscle and Scars", additional_info = "[q]You deal 5% more damage and take 5.0% less damage.\n\n Size increased by 5%."}
MultiLanguageSpellData['en'][429643] = {name = "Steamroller", additional_info = "[q]Arms:\n Shockwave and Whirlwind increase the pass-through damage of your next Juggernaut Crash by 10% stacks up to 3 times.\n\n Protection:\n Shockwave and Revenge increase the pass-through damage of your next Juggernaut Crash by 10% stacks up to 3 times."}
