MultiLanguageSpellData['en'][430590] = {name = "Algari Healing Potion", additional_info = "2 sec cast 2\nReagents:\nMycobloom (6), Gilded Vial (5)\nOptional Reagents:\n\n[q2]Use: Restores ( 99607 - 99607 %50) health.\n71"}
MultiLanguageSpellData['en'][430591] = {name = "Algari Mana Potion", additional_info = "2 sec cast 2\nReagents:\nMycobloom (6), Blessing Blossom (3), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Restores 13707 mana.\n71"}
MultiLanguageSpellData['en'][430592] = {name = "Cavedweller's Delight", additional_info = "2 sec cast 2\nReagents:\nMycobloom (8), Luredrop (4), Orbinid (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Restores ( 106918 - 106918 %50) health and 14012 mana.\n71"}
MultiLanguageSpellData['en'][430593] = {name = "Slumbering Soul Serum", additional_info = "2 sec cast 2\nReagents:\nMycobloom (4), Blessing Blossom (5), Arathor's Spear (5), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Elevate your focus to restore ( 207 * 10) mana over 10 sec, but you are defenseless until your focus is broken.\n71"}
MultiLanguageSpellData['en'][430594] = {name = "Draught of Silent Footfalls", additional_info = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (8), Luredrop (3), Orbinid (3), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: The imbiber gains invisibility for 12-18 sec (based on crafting quality). (5 Min Cooldown)\n71"}
MultiLanguageSpellData['en'][430595] = {name = "Draught of Shocking Revelations", additional_info = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (4), Orbinid (6), Arathor's Spear (2), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Gain increased stealth detection. Every 1 sec, the light will attempt to smite a hidden foe within 20 yds.\n\n Lasts for 15-25 sec (based on crafting quality).\n71"}
MultiLanguageSpellData['en'][430596] = {name = "Grotesque Vial", additional_info = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Luredrop (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: While dead, twitch to spill a vial and dissolve yourself into a puddle of rejuvenating ooze. Up to 3 allies who step through you are healed for 2683 every 2 sec over 6 sec.\n\n Shares a cooldown with healing potions.\n71"}
MultiLanguageSpellData['en'][430597] = {name = "Potion of Unwavering Focus", additional_info = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (12), Orbinid (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Fixate on the target enemy within 40 yds to increase your damage dealt to them by 2-4% (based on item quality). Lasts 20 sec.\n71"}
MultiLanguageSpellData['en'][430598] = {name = "Frontline Potion", additional_info = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (12), Blessing Blossom (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Consume to gain 10 armor and 2% maximum health for 6 sec. Whenever you are struck, gain an additional stack of these effects and increase the duration by 1 sec, up to 9 times. (500ms cooldown)\n71"}
MultiLanguageSpellData['en'][430599] = {name = "Tempered Potion", additional_info = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Luredrop (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Gain the effects of all inactive Tempered Flasks, increasing their associated secondary stats by 48 for 30 sec.\n71"}
MultiLanguageSpellData['en'][430600] = {name = "Potion of the Reborn Cheetah", additional_info = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Orbinid (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your movement speed by 60% for 12-20 sec (based on item quality). You will become dazed if struck.\n71"}
MultiLanguageSpellData['en'][430601] = {name = "Flask of Tempered Aggression", additional_info = "2 sec cast 2\nReagents:\nNull Lotus , Viridescent Spores (2), Luredrop (12), Orbinid (12), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Critical Strike by 51 .\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430602] = {name = "Flask of Tempered Swiftness", additional_info = "2 sec cast 2\nReagents:\nNull Lotus , Leyline Residue (2), Luredrop (12), Blessing Blossom (12), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Haste by 51 .\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430603] = {name = "Flask of Tempered Versatility", additional_info = "2 sec cast 2\nReagents:\nNull Lotus , Viridescent Spores (2), Orbinid (12), Arathor's Spear (12), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Versatility by 51 .\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430604] = {name = "Flask of Tempered Mastery", additional_info = "2 sec cast 2\nReagents:\nNull Lotus , Leyline Residue (2), Blessing Blossom (12), Arathor's Spear (12), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Mastery by 51 .\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430605] = {name = "Flask of Alchemical Chaos", additional_info = "2 sec cast 2\nReagents:\nNull Lotus , Luredrop (8), Orbinid (8), Blessing Blossom (8), Arathor's Spear (8), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase a random secondary stat by 63 at the cost of 5 of two other secondary stats. These effects are randomized again every 30 sec.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430607] = {name = "Vicious Flask of Classical Spirits", additional_info = "2 sec cast 2\nReagents:\nVicious Flask of Honor , Orbinid (6)\nVendor:\nHotharn\nZone:\nDornogal\nCost:\n7500\n\n[q2]Use: Drink to increase your mana regeneration by 8% whenever you have not cast a beneficial spell that costs mana for 5 sec.\n\n Honor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430608] = {name = "Vicious Flask of Honor", additional_info = "2 sec cast 2\nReagents:\nMycobloom (16), Blessing Blossom (8), Gilded Vial (2)\nVendor:\nHotharn\nZone:\nDornogal\nCost:\n7500\n\n[q2]Use: Drink to increase honor gains by 15%. Can be used in all rated and unrated PvP environments.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
