MultiLanguageSpellData['en'][430611] = {name = "Vicious Flask of the Wrecking Ball", additional_info = "2 sec cast 2\nReagents:\nVicious Flask of Honor , Arathor's Spear (6)\nVendor:\nHotharn\nZone:\nDornogal\nCost:\n7500\n\n[q2]Use: Player killing blows increase your damage dealt by 8% and damage taken by 4% for 20 sec, stacking up to 5 times. If you are slain with this effect, your assailant takes a portion of this power.\n\n Honor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430612] = {name = "Flask of Saving Graces", additional_info = "2 sec cast\nReagents:\nNull Lotus , Mycobloom (16), Blessing Blossom (8), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Directly healing an ally player that is below 20% health grants 5-10% (based on crafting quality) increased healing done for 10 sec.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71"}
MultiLanguageSpellData['en'][430614] = {name = "Phial of Concentrated Ingenuity", additional_info = "2 sec cast\nReagents:\nLeyline Residue , Luredrop (5), Orbinid (5), Blessing Blossom (5), Gilded Vial (4)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Ingenuity for all Khaz Algar professions by 1 .\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n71"}
MultiLanguageSpellData['en'][430615] = {name = "Phial of Truesight", additional_info = "2 sec cast\nReagents:\nViridescent Spores , Mycobloom (5), Luredrop (5), Blessing Blossom (5), Gilded Vial (4)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Perception by 1 and allow you to see camouflaged mining and herbalism nodes.\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n71"}
MultiLanguageSpellData['en'][430616] = {name = "Phial of Enhanced Ambidexterity", additional_info = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (5), Luredrop (5), Orbinid (5), Gilded Vial (4)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Crafting Speed and Deftness by 5-15% (based on crafting quality).\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n71"}
MultiLanguageSpellData['en'][430617] = {name = "Phial of Bountiful Seasons", additional_info = "2 sec cast\nReagents:\nWrithing Sample , Luredrop (3), Orbinid (3), Blessing Blossom (3), Arathor's Spear (6), Gilded Vial (4)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\n\n[q2]Use: Drink to increase your Finesse by 1 during the Summer or your Resourcefulness by 1 during the Winter. Only applies to Khaz Algar professions.\n\nLasts 30 min and through death. Consuming an identical phial will add another 30 min.\n71"}
