MultiLanguageSpellData['en'][432962] = {name = "[q4]Algari Flask Cauldron", additional_info = "2 sec cast 3\nReagents:\nCrystalforged Cauldron , Coreway Catalyst (25), Vial of Kaheti Oils (3), Gilded Vial (20), Harmonious Horticulture (8)\nOptional Reagents:\nSpecialization:\nFantastic Flasks (30)\n\n[q4]Algari Flask Cauldron\n[q7]Binds to Warband\n\n[q2]Use: Place a cauldron that allows party and raid members to take flasks of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\n The cauldron lasts for 5 min and has 40 charges. You will receive the Crystalforged Cauldron back once used.\n71"}
MultiLanguageSpellData['en'][432963] = {name = "[q4]Algari Potion Cauldron", additional_info = "2 sec cast 3\nReagents:\nCrystalforged Cauldron , Coreway Catalyst (40), Viridian Charmcap (5), Gilded Vial (80), Harmonious Horticulture (8)\nOptional Reagents:\nSpecialization:\nPotent Potions (30)\n\n[q4]Algari Potion Cauldron\n[q7]Binds to Warband\n\n[q2]Use: Place a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\n The cauldron lasts for 5 min and has 80 charges. Each charge grants 5 potions. You will receive the Crystalforged Cauldron back once used.\n71"}
