MultiLanguageSpellData['en'][435138] = {name = "Digestive Acid", additional_info = "300 yd range\n2 sec cast\n[q]Ulgrax belches Digestive Acid at several players, inflicting 1726895 Nature damage every 2 sec for 6 sec.\n\n Once removed venom erupts the victim's skin, inflicting 1151263 Nature damage to players within 7 yards and dissolving any webbing left behind by Stalker's Webbing ."}
MultiLanguageSpellData['en'][435140] = {name = "Into the Machine - Abandon", additional_info = nil}
MultiLanguageSpellData['en'][435141] = {name = "Pact of the Deathbringer", additional_info = "[q]When you suffer a damaging effect equal to 2% of your maximum health, you instantly cast Death Pact at 25% effectiveness. Can only occur every 50 min.\n\n When a Reaper's Mark explodes, the cooldowns of this effect and Dark Pact are reduced by 25 sec."}
MultiLanguageSpellData['en'][435142] = {name = "Into the Machine - Abandon - Teleport", additional_info = nil}
MultiLanguageSpellData['en'][435143] = {name = "Phase Blades", additional_info = "Unlimited range\nChanneled (1.5 sec cast)\n[q]Sikran marks players and lunges towards each marked target inflicting 3741605 Physical damage to anyone in his path.\n\n Additionally, players hit have their healing received reduced by 50% and an additional 474896 Shadow damage inflicted every 2 sec for 20 sec.\n\n Marked targets leave behind a Cosmic Simulacrum when struck."}
MultiLanguageSpellData['en'][435144] = {name = "Impaling Shards", additional_info = "[q]Each time Permafrost shield takes damage, it has a chance to scatter icy shards to nearby enemies for (5% of Attack Power) Frost damage and reduce the damage the targets deal to you by 5% for 5 sec."}
MultiLanguageSpellData['en'][435145] = {name = "Bloody Skyscreamer", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This dinosaur still harbors the rage of its ancestors from the Zandalari Invasion.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['en'][435146] = {name = "Night Pterrorwing", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Scholars interpret this creature's awful screeching as \"fear me, I am the night!\"\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['en'][435147] = {name = "Jade Pterrordax", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This favored mount of the Zandalari is a great singer, or so it thinks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['en'][435148] = {name = "Blazing Strike", additional_info = "8 yd range\n1.5 sec cast\n[q]Inflicts 4848899 Holy damage and an additional 484890 Holy damage every 1 sec for 10 sec."}
MultiLanguageSpellData['en'][435149] = {name = "Cobalt Juggernaut", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"What started as a rideable mining and logging machine devolved quickly into chaos when engineers asked themselves if they could make it any cooler.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['en'][435150] = {name = "Fel Iron Juggernaut", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This war machine was stolen from a timeline in which Garrosh Hellscream joined the Burning Legion. Suffice it to say, there is not much left of that timeline.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['en'][435151] = {name = "Eye of the Swarm", additional_info = "Unlimited range\nInstant\n[q]Upon reaching 100 energy, Anub’zekt calls forth a massive swarm surrounding the arena. While within the biting insect swarm, players rapidly gain applications of Ceaseless Swarm."}
