MultiLanguageSpellData['en'][435323] = {name = "Gilded Vial", additional_info = "2 sec cast 2\nTools: Jeweler's Tools\nReagents:\nGlittering Glass (6), Ambivalent Amber , Crushed Gemstones (3)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Jewelcrafting (15)\nCost:\n115\n\nCrafting Reagent\n[q]\"Purchased from tradeskill vendors. Jewelcrafters can also craft this item at equal or higher qualities. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][435324] = {name = "Engraved Gemcutter", additional_info = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nHandful of Pebbles (5), Glittering Glass , Bismuth (5)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Jewelcrafting (1)\nCost:\n100\n\nCrafting Reagent\n[q]\"Created by players with the Jewelcrafting skill for the purpose of cutting Khaz Algar gems. Can be bought and sold on the Auction House.\""}
