MultiLanguageSpellData['en'][435329] = {name = "[q3]Sifted Cave Sand", additional_info = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nMarbled Stone (15)\nOptional Reagents:\nVendor:\nAlvus Valavulu\nZone:\nCity of Threads\nCost:\n150\n1500\n\n[q3]Sifted Cave Sand\nFinishing Crafting Reagent\n\n[q2]When crafting: Increases Resourcefulness by 150 and reagents saved from Resourcefulness by 12%.\n[q]Usable with: Many Inscription recipes.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][435330] = {name = "[q3]Ominous Energy Crystal", additional_info = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nCrushed Gemstones (5)\nOptional Reagents:\nVendor:\nAlvus Valavulu\nZone:\nCity of Threads\nCost:\n150\n1500\n\n[q3]Ominous Energy Crystal\nFinishing Crafting Reagent\n\n[q2]When crafting: Increases Ingenuity by 300.\n[q]Usable with: Many Jewelcrafting recipes except gem cuts. Engineers seem interested in this, too.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][435331] = {name = "[q3]Elemental Focusing Lens", additional_info = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNull Stone , Decorative Lens\nOptional Reagents:\nSpecialization:\nShaping - Glasswork (15)\n\n[q3]Elemental Focusing Lens\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Your spells and abilities have a chance to deal bonus magic damage. The chosen school is based on socketed gems.\n\n Unique-Equipped: Embellished 2.\n[q]Usable with: Khaz Algar recipes for most unembellished equipment.\n[q]\"Can be bought and sold on the Auction House.\""}
