MultiLanguageSpellData['en'][438592] = {name = "Serum of Unconstrained Pleasure", additional_info = "{Instant} {1 min cooldown}\n[q]Systematically consume a small dosage of the serum when entering combat heightening your senses to their limit.\n In this state parrying and dodging have a chance to cause you to reposte with a Counter dealing Y Physical damage to your assailant."}
MultiLanguageSpellData['en'][438593] = {name = "Snack Time", additional_info = "100 yd range\nInstant\n[q]Benk Buzzbee summons barrels of delicious honey. The collision inflicts 12122247 Physical damage to players standing within 3 yards of the impact.\n\n The honey's aroma attracts a Ravenous Cinderbee every 30 sec."}
MultiLanguageSpellData['en'][438595] = {name = "Excess Fire", additional_info = "[q]Frost\n Casting Comet Storm causes your next Ice Lance to explode in a Frostfire Burst, dealing (265.6% of Spell Power) Frostfire damage to nearby enemies. Damage reduced beyond 8 targets.\n\n Frostfire Burst has an 50% chance to grant Brain Freeze.\n\nFire\n Casting Meteor causes your next Fire Blast to explode in a Frostfire Burst, dealing (265.6% of Spell Power) Frostfire damage to nearby enemies. Damage reduced beyond 8 targets.\n\n Frostfire Burst reduces the cooldown of Phoenix Flames by 5 sec."}
