MultiLanguageSpellData['en'][438598] = {name = "Storm Shield", additional_info = "Unlimited range\nInstant\n[q]Intervening a target grants them a shield for 5 sec that absorbs magic damage equal to 3 times your Armor."}
MultiLanguageSpellData['en'][438599] = {name = "Bleeding Jab", additional_info = "40 yd range\nInstant\n[q]Jabs a player and causes them to bleed, inflicting 181834 Physical damage every 0.5 sec for 3 sec. This effect stacks."}
MultiLanguageSpellData['en'][438600] = {name = "Excess Frost", additional_info = "[q]Frost\n Consuming Excess Fire causes your next Flurry to also cast Ice Nova at 150% effectiveness. Ice Novas cast this way do not freeze enemies in place.\n\n When you consume Excess Frost, the cooldown of Comet Storm is reduced by 3 sec.\n\nFire\n Consuming Excess Fire causes your next Phoenix Flames to also cast Ice Nova at 200% effectiveness. Ice Novas cast this way do not freeze enemies in place.\n\n When you consume Excess Frost, the cooldown of Meteor is reduced by 5 sec."}
