MultiLanguageSpellData['en'][438607] = {name = "Meteor", additional_info = "100 yd range\nInstant\n[q]Calls down a meteor which lands at the target location after 3 sec, dealing (444% of Spell Power) Fire damage to all enemies, and burns the ground, dealing [8 * (8.53875% of Spell Power)] Fire damage over 8.5 sec to all enemies in the area.\n\n The enemy closest to the center of the Meteor's impact takes 40% increased damage. Damage reduced beyond 8 targets."}
