MultiLanguageSpellData['en'][443533] = {name = "Tome of Light's Devotion", additional_info = "[q]Advance to the 50 Verses of Inner Resilience, reading as you are attacked.\n Inner Resilience increases your armor by 136 and grants your attacks a chance to invoke a ward which absorbs 3376 Magic damage. When finished, sift through the passages to another chapter.\n\nValid only for tank specializations.\n(500ms cooldown)"}
