MultiLanguageSpellData['en'][443535] = {name = "Tome of Light's Devotion", additional_info = "{Instant} {1.5 min cooldown}\n[q]Sift through the passages in the tome with increased Radiance ."}
MultiLanguageSpellData['en'][443536] = {name = "Bursting Lightshard", additional_info = "35 yd range\n{Instant} {2 min cooldown}\n[q]Summon a Bursting Lightspawn which sacrifices its health to unleash Bursts of Light, inflicting 1446 Holy damage split between nearby enemies every 2 sec while it lives."}
MultiLanguageSpellData['en'][443537] = {name = "Void Pactstone", additional_info = "Approximately 2 procs per minute\n[q]Your attacks have a chance to call to the pact, exploding for ( 1 * 897 ) Shadow damage split between nearby enemies and increasing your Haste by 36 for 10 sec.\n\n Your death breaks the pact, causing a violent explosion."}
MultiLanguageSpellData['en'][443538] = {name = "Empowering Crystal of Anub'ikkaj", additional_info = "Approximately 1.55 procs per minute\n[q]Your spells and abilities have a chance to let loose a nascent empowerment from the crystal, increasing a random secondary stat by 131 for 20 sec."}
MultiLanguageSpellData['en'][443539] = {name = "Mereldar's Toll", additional_info = "50 yd range\nInstant\n[q]Release a toll of holy light upon the target, inflicting ( 1 * 1368 ) Holy damage. The next 5 allies to attack the target will receive the Blessing of Mereldar, increasing their Versatility by 62 for 10 sec."}
MultiLanguageSpellData['en'][443541] = {name = "Ara-Kara Sacbrood", additional_info = "Approximately 2.5 procs per minute\n[q]Your abilities have a chance to stir the sac, releasing an egg which grants you 15 Primary Stat. Each egg hatches after 1 min, and the new brood attacks your next target, inflicting ( 1 * 80 * 8) Nature damage over 8 sec.\n(100ms cooldown)"}
MultiLanguageSpellData['en'][443544] = {name = "Refracting Aggression Module", additional_info = "[q]Your taunt abilities activate the module's refracting energy, protecting you from 50% of damage taken, up to 7648 . This may only occur once every 1 min.\n\nValid only for tank specializations.\n(1m cooldown)"}
MultiLanguageSpellData['en'][443545] = {name = "Ceaseless Swarmgland", additional_info = "Approximately 6 procs per minute\n[q]The gland releases pheromones that attract a Ceaseless Swarm of insects to surround you. Taking damage has a high chance to retaliate against attackers, inflicting ( 69 * 6) Nature damage over 6 sec and reducing damage dealt to you by 96 ."}
MultiLanguageSpellData['en'][443549] = {name = "Harvester's Edict", additional_info = "100 yd range\nInstant\n[q]Your damaging spells and abilities have a chance to send an orb of volatile black blood drifting to your target, exploding for ( 1 * 1418 ) Shadow damage split between all nearby enemies on impact. Intercepting the orb allows you to siphon its power, instead increasing your Mastery by 156 for 15 sec."}
MultiLanguageSpellData['en'][443552] = {name = "Oppressive Oration", additional_info = "{Instant} {2 min cooldown}\n[q]Wave the larynx in the air to release a tormenting chorus, inflicting ( 1 * 1480 * 3) Shadow damage over 3 sec split between nearby enemies. Your whispers leave to join the chorus, increasing its damage before falling silent."}
MultiLanguageSpellData['en'][443553] = {name = "Moose Charge Knockback", additional_info = "Unlimited range\nInstant\n[q]Charge to the target, ramming them and knocking them backwards."}
MultiLanguageSpellData['en'][443556] = {name = "Twin Fang Instruments", additional_info = "{Instant} {2 min cooldown}\n[q]Open the pouch and draw Nx's shadow blade to quickly strike at enemies in front of you, inflicting ( 1 * 585 ) Shadow damage to all enemies hit.\n\n You may use the pouch up to two additional times within 20 sec before it seals itself to magically recharge its contents."}
MultiLanguageSpellData['en'][443557] = {name = "Viscous Coaglam", additional_info = "[q]Your excessive healing attracts nearby shadow energy to your party, storing up to 213 healing and restoring the target's health when they receive damage."}
MultiLanguageSpellData['en'][443558] = {name = "Coagulated Membrane", additional_info = "46 yd range\n{Instant} {1 min cooldown}\n[q]Channel the coaglam's power, concentrating all current shadow energy to shield your target."}
MultiLanguageSpellData['en'][443559] = {name = "Cirral Concoctory", additional_info = "Approximately 2 procs per minute\n[q]Your spells have a chance to inspire you to experiment on an ally, enhancing them in unforeseen ways for 20 sec."}
MultiLanguageSpellData['en'][443560] = {name = "Swift and Painful", additional_info = "[q]Blood\n If no enemies are struck by Soul Rupture, you gain 10% Strength for 8 sec.\n\n Wave of Souls is 100% more effective on the main target of your Reaper's Mark.\n\nFrost\n If no enemies are struck by Soul Rupture, you gain 5% Strength for 8 sec.\n\n Wave of Souls is 50% more effective on the main target of your Reaper's Mark."}
