MultiLanguageSpellData['en'][444190] = {name = "[q3]Codified Greenwood", additional_info = "3.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nDistilled Algari Freshwater (20), Arathor's Spear (5), Shadow Ink (2)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Inscription (25)\nCost:\n160\n\n[q3]Codified Greenwood\nCrafting Reagent\n\n[q2]Provides the following property: DNT does something awesome\n[q]\"A refined piece of Arathor's Spear. Crafted by players with the Inscription skill. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][444191] = {name = "[q3]Boundless Cipher", additional_info = "3.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nDistilled Algari Freshwater (20), Arathor's Spear (5), Apricate Ink (2)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Inscription (20)\nCost:\n150\n\n[q3]Boundless Cipher\nCrafting Reagent\n\n[q2]Provides the following property: DNT does something awesome\n[q]\"A boundless rune crafted by players with the Inscription skill. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][444192] = {name = "[q3]Darkmoon Sigil: Ascension", additional_info = "3.5 sec cast\nReagents:\nDarkmoon Deck: Ascension , Writhing Sample (8), Boundless Cipher (4), Shadow Ink (4)\nOptional Reagents:\nSpecialization:\n\n\n[q3]Darkmoon Sigil: Ascension\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Gain Ascendance every 8 seconds spent in combat.\n\nAscendance grants 4 of a random secondary stat for 15 sec, stacking up to 10 times.\n\n This is a Nerubian embellishment.\n\n Unique-Equipped: Embellished 2.\n[q]Usable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][444193] = {name = "[q3]Darkmoon Sigil: Radiance", additional_info = "3.5 sec cast\nReagents:\nDarkmoon Deck: Radiance , Writhing Sample (8), Boundless Cipher (4), Apricate Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Radiance\n\n[q3]Darkmoon Sigil: Radiance\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Your damaging spells and abilities have the chance to ignite your target with Radiant Focus for 15 sec.\n\n After dealing up to 18842 damage to the target, the focused energies ignite you with Radiance, granting between ( 35 * .5) to 35 of your highest Secondary stat based on damage dealt for 15 sec.\n\n Unique-Equipped: Embellished 2.\n[q]Usable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][444194] = {name = "[q3]Darkmoon Sigil: Symbiosis", additional_info = "3.5 sec cast\nReagents:\nDarkmoon Deck: Symbiosis , Writhing Sample (8), Boundless Cipher (4), Shadow Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Symbiosis\n\n[q3]Darkmoon Sigil: Symbiosis\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Every 10 seconds in combat take 1% of your maximum Health as Nature damage and gain a stack of Symbiosis, granting 3 Versatility for 20 sec stacking up to 5 times.\n\n This is a Nerubian embellishment.\n\n Unique-Equipped: Embellished 2.\n[q]Usable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][444195] = {name = "[q3]Darkmoon Sigil: Vivacity", additional_info = "3.5 sec cast\nReagents:\nDarkmoon Deck: Vivacity , Writhing Sample (8), Boundless Cipher (4), Apricate Ink (4)\nOptional Reagents:\nSpecialization:\nArchival Additions - Darkmoon Sigil: Vivacity\n\n[q3]Darkmoon Sigil: Vivacity\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Your damaging spells and abilities have the chance to grant Vivaciousness, increasing secondary stats by 4 and Speed or Avoidance by 2 based on the school it was activated from.\n\n Unique-Equipped: Embellished 2.\n[q]Usable with: Khaz Algar recipes for most unembellished weapons and off-hands.\n[q]\"Can be bought and sold on the Auction House.\""}
