MultiLanguageSpellData['en'][444827] = {name = "Reactive Barrier", additional_info = "[q]Frost\n Your Ice Barrier can absorb up to 50% more damage based on your missing Health.\n\n Max effectiveness when under 50% health.\n\nArcane\n Your Prismatic Barrier can absorb up to 50% more damage based on your missing Health.\n\n Max effectiveness when under 50% health."}
