MultiLanguageSpellData['en'][444829] = {name = "Queen's Summons", additional_info = "3 sec cast\n[q]Ansurek lets forth a ghastly shriek, inflicting 2878158 Shadow damage to all players and calling Summoned Acolytes to her aid.\n\n Upon death, they become Acolyte's Essence ."}
