MultiLanguageSpellData['en'][445024] = {name = "Whirling Elements", additional_info = "[q]Enhancement\n Elemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects.\n\nAir: [ Enhancement : Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem /\n\nElemental, Restoration\nThe cast time of your next healing spell is reduced by 40% ]\nEarth: [ Enhancement : Direct damage of your next Flame Shock is increased by 300% and it is applied to 5 nearby enemies /\n\nElemental, Restoration\nYour next Chain Heal applies Earthliving at 150% effectiveness to all targets hit ]\nFire: Your next Lava Lash or Fire Nova grants you Hot Hand for 6 sec.\n\nRestoration\n Elemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects.\n\nWater: Your next Healing Wave or Healing Surge also heals an ally inside of your Healing Rain at 100% effectiveness.\n\nAir: [ Enhancement : Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem /\n\nElemental, Restoration\nThe cast time of your next healing spell is reduced by 40% ]\nEarth: [ Enhancement : Direct damage of your next Flame Shock is increased by 300% and it is applied to 5 nearby enemies /\n\nElemental, Restoration\nYour next Chain Heal applies Earthliving at 150% effectiveness to all targets hit ]"}
MultiLanguageSpellData['en'][445025] = {name = "Totemic Rebound", additional_info = "Approximately 10 procs per minute\n[q]Restoration\n Chain Heal now jumps to a nearby totem within 20 yards once it reaches its last target, causing the totem to cast Chain Heal on an injured ally within 30 yards for (150% of Spell Power). Jumps to 2 nearby targets within 20 yards.\n\nEnhancement\n Lightning Bolt, Chain Lightning and Elemental Blast has a chance to unleash a Surging Bolt at your Surging Totem, increasing the totem's damage by 10%, and then redirecting the bolt to your target for (92% of Attack Power) Nature damage. The damage bonus effect can stack."}
MultiLanguageSpellData['en'][445026] = {name = "Oversized Totems", additional_info = "[q]Increases the size and radius of your totems by 15%, and the health of your totems by 30%."}
MultiLanguageSpellData['en'][445027] = {name = "Swift Recall", additional_info = "[q]Successfully removing a harmful effect with Tremor Totem or Poison Cleansing Totem, or controlling an enemy with Capacitor Totem or Earthgrab Totem reduces the cooldown of the totem used by 5 sec.\n\n Cannot occur more than once every 20 sec per totem."}
MultiLanguageSpellData['en'][445028] = {name = "Imbuement Mastery", additional_info = "[q]Enhancement\n Increases the chance for Windfury Weapon to trigger by 5% and increases its damage by 8%.\n\n When Flametongue Weapon triggers from Windfury Weapon attacks, it has a chance to gather a whirl of flame around the target, dealing 300% of its damage to all nearby enemies.\n\nRestoration\n Increases the duration of your Earthliving effect by 3 sec."}
MultiLanguageSpellData['en'][445029] = {name = "Amplification Core", additional_info = "[q]While Surging Totem is active, your damage and healing done is increased by 3%."}
MultiLanguageSpellData['en'][445030] = {name = "Oversurge", additional_info = "[q]Restoration\n Surging Totem deals 50% more damage during Ascendance.\n\nEnhancement\n Surging Totem deals 50% more damage during Ascendance."}
