MultiLanguageSpellData['en'][445317] = {name = "[q3]Stormrider's Fury", additional_info = "3.5 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nRinging Deeps Ingot , Storm Dust (50), Gleaming Shard (5), Refulgent Crystal\nOptional Reagents:\n[q]Earthen Enhancements - Wondrous Weapons\n\n Permanently enchants a weapon to sometimes grant you Storm's Fury, bestowing 16 Haste to you for 12 sec. Cannot be applied to items lower than level 70.\nProfession Trainer:\nKhaz Algar Enchanting (55)\nCost:\n180\n\n[q3]Enchant Weapon - Stormrider's Fury\n\n[q2]Use: Earthen Enhancements - Wondrous Weapons\n\n Permanently enchants a weapon to sometimes grant you Storm's Fury, bestowing 24 Haste to you for 12 sec. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445318] = {name = "[q2]Oil of Beledar's Grace", additional_info = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Crystalline Powder (2), Storm Dust (10), Gleaming Shard\nOptional Reagents:\nSpecialization:\nEphemerals, Enrichments, and Equipment - Optimal Oils\n\n[q2]Oil of Beledar's Grace\n\n[q2]Use: Coat your weapon in an oil that emits a warm light. The oil has a chance to resonate with your healing, healing an additional 1419 Health to the target.\n\n Lasts 120 min.\n68\n[q]\"The vial of oil radiates with the warm light of Beledar.\""}
MultiLanguageSpellData['en'][445319] = {name = "Gleeful Glamour - Orc", additional_info = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nLeyline Residue , Viridescent Spores , Storm Dust (5)\nOptional Reagents:\nSpecialization:\nEphemerals, Enrichments, and Equipment - Deceptive Decorations\n\n\n[q2]Use: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\n Lasts 20-60 min. based on the quality of the Gleeful Glamour."}
MultiLanguageSpellData['en'][445320] = {name = "[q3]Radiant Haste", additional_info = "3.5 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (30), Gleaming Shard (5)\nOptional Reagents:\n[q]Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a ring with Beledar's radiance, increasing Haste by 15. Cannot be applied to items lower than level 70.\nDrop:\nPrioress Murrpray\nZone:\nPriory of the Sacred Flame\n\nTreasure:\nChallenger's Cache\nZone:\nThe Dawnbreaker\n\n[q3]Enchant Ring - Radiant Haste\n\n[q2]Use: Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a ring with Beledar's radiance, increasing Haste by 15. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445321] = {name = "[q3]Oathsworn's Strength", additional_info = "3.5 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nCrystalline Powder (10), Ringing Deeps Ingot , Storm Dust (75), Gleaming Shard (10), Refulgent Crystal\nOptional Reagents:\n[q]Earthen Enhancements - Bolstered Breastplates\n\n Permanently enchants a chestpiece to increase your Strength by 24 and Stamina by 12. Cannot be applied to items lower than level 70.\nDrop:\nAwakening the Machine\n\n[q3]Enchant Chest - Oathsworn's Strength\n\n[q2]Use: Earthen Enhancements - Bolstered Breastplates\n\n Permanently enchants a chestpiece to increase your Strength by 24 and Stamina by 12. Cannot be applied to items lower than level 70.\n70"}
