MultiLanguageSpellData['en'][445333] = {name = "[q3]Crystalline Radiance", additional_info = "3.5 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nCrystalline Powder (20), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal\nOptional Reagents:\n[q]Earthen Enhancements - Bolstered Breastplates\n\n Permanently enchants a chestpiece with Earthen rune magic to increase your Primary Stat by 34. Cannot be applied to items lower than level 70.\nSpecialization:\nEverlasting Enchantments - Bolstered Breastplates\n\n[q3]Enchant Chest - Crystalline Radiance\n\n[q2]Use: Earthen Enhancements - Bolstered Breastplates\n\n Permanently enchants a chestpiece with Earthen rune magic to increase your Primary Stat by 34. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445334] = {name = "[q3]Chant of Armored Avoidance", additional_info = "3.5 sec cast 2\nRequires Bracers\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Storm Dust (40), Gleaming Shard (5)\nOptional Reagents:\n[q]Nerubian Novelties - Tertiary Trivialities\n\n Permanently enchants bracers with ancient magic that chants with power, granting 50 Avoidance. Cannot be applied to items lower than level 70.\nVendor:\nIliani\nZone:\nCity of Threads\nCost:\n150\n1500\n\nVendor:\nVenomscribe Xesh XI\nZone:\nCity of Threads\nCost:\n150\n1500\n\n[q3]Enchant Bracer - Chant of Armored Avoidance\n\n[q2]Use: Nerubian Novelties - Tertiary Trivialities\n\n Permanently enchants bracers with ancient magic that chants with power, granting 50 Avoidance. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445335] = {name = "[q3]Cavalry's March", additional_info = "3.5 sec cast\nRequires Boots\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (30), Gleaming Shard (5)\nOptional Reagents:\n[q]Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a pair of boots with the cavalry's fleetness, increasing mounted speed by 6%. Cannot be applied to items lower than level 70.\nVendor:\nLyrendal\nZone:\nDornogal\nCost:\n150\n\n[q3]Enchant Boots - Cavalry's March\n\n[q2]Use: Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a pair of boots with the cavalry's fleetness, increasing mounted speed by 6%. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445336] = {name = "[q3]Authority of Storms", additional_info = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nRinging Deeps Ingot , Bottled Storm (5), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\n[q]Earthen Enhancements - Wondrous Weapons\n\n Permanently enchants a weapon with the Authority of Storms. Your abilities have a chance to imbue you, causing further abilities to sometimes unleash lightning which deals ( 1 * 2014) Nature damage split amongst all enemies hit. Cannot be applied to items lower than level 70.\nSpecialization:\nEverlasting Enchantments - Wondrous Weapons\n\n[q3]Enchant Weapon - Authority of Storms\n\n[q2]Use: Earthen Enhancements - Wondrous Weapons\n\n Permanently enchants a weapon with the Authority of Storms. Your abilities have a chance to imbue you, causing further abilities to sometimes unleash lightning which deals ( 1 * 2014) Nature damage split amongst all enemies hit. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445337] = {name = "[q3]Illusory Adornment: Shadow", additional_info = "3.5 sec cast\nRequires Shoulders\nTools: Runed Enchanting Rod\nReagents:\nWrithing Sample (5), Storm Dust (3)\nOptional Reagents:\n[q]Temporarily imbues shoulders with a shadowed illusion for 20 min.\nDrop:\nSevered Threads Pact\n\n[q3]Illusory Adornment: Shadow\n\n[q2]Use: Temporarily imbues shoulders with a shadowed illusion for 20 min.\n70"}
MultiLanguageSpellData['en'][445338] = {name = "[q2]Algari Mana Oil", additional_info = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nLeyline Residue (10), Storm Dust (5)\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Enchanting (20)\nCost:\n110\n\n[q2]Algari Mana Oil\n\n[q2]Use: Coat your weapon in Algari Mana Oil, increasing your Critical Strike and Haste by 5 for 120 min.\n68\n[q]\"The oil radiates a subtle, but noticeable magical aura.\""}
MultiLanguageSpellData['en'][445339] = {name = "[q3]Authority of Radiant Power", additional_info = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nProfaned Tinderbox , Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\n[q]Arathor Alterations - Fortified Flames\n\n Permanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 1681) Radiant damage and temporarily increasing your Primary stat by 14. Cannot be applied to items lower than level 70.\nDrop:\nPrioress Murrpray\nZone:\nPriory of the Sacred Flame\n\n[q3]Enchant Weapon - Authority of Radiant Power\n\n[q2]Use: Arathor Alterations - Fortified Flames\n\n Permanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 1681) Radiant damage and temporarily increasing your Primary stat by 14. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445340] = {name = "[q3]Glimmering Versatility", additional_info = "3.5 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nStorm Dust (5)\nOptional Reagents:\n[q]Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a ring with a glimmer of Beledar, increasing Versatility by 9. Cannot be applied to items lower than level 70.\nProfession Trainer:\nKhaz Algar Enchanting (45)\nCost:\n160\n\n[q3]Enchant Ring - Glimmering Versatility\n\n[q2]Use: Arathor Alterations - Accentuated Accessories\n\n Permanently enchants a ring with a glimmer of Beledar, increasing Versatility by 9. Cannot be applied to items lower than level 70.\n70"}
MultiLanguageSpellData['en'][445341] = {name = "[q3]Authority of the Depths", additional_info = "3.5 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nVial of Kaheti Oils , Writhing Sample (5), Storm Dust (75), Gleaming Shard (10), Refulgent Crystal (2)\nOptional Reagents:\n[q]Nerubian Novelties\n\n Permanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 242) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 70.\nDrop:\nQueen Ansurek\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\n\n[q3]Enchant Weapon - Authority of the Depths\n\n[q2]Use: Nerubian Novelties\n\n Permanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 242) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 70.\n70"}
