MultiLanguageSpellData['en'][445475] = {name = "Surekian Barrage", additional_info = "Instant\n[q]Draw a bow from the Arsenal to unleash a barrage of arrows in front of you, dealing ( 1 * 1478 ) Shadow damage to all enemies within 20 yards.\n\n Until the next weapon is drawn, remain stationary to increase your speed by 6% for 6 sec upon moving, increased by an additional 6% every 2 sec, up to 5 times."}
MultiLanguageSpellData['en'][445479] = {name = "[q2]Cinder Nectar", additional_info = "2 sec cast\nReagents:\nDelver's Waterskin (3), Hot Honeycomb\nOptional Reagents:\nSecret Ingredient (#318)\n[q]Recipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCendvin\nZone:\nIsle of Dorn\nCost:\n120\n\n[q2]Cinder Nectar\n[q2]Use: Restores ( 937500 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n68"}
MultiLanguageSpellData['en'][445480] = {name = "[q2]Pep-In-Your-Step", additional_info = "2 sec cast\nReagents:\nDelver's Waterskin (5)\nOptional Reagents:\nSecret Ingredient (#318)\n[q]Recipe for 1 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\n[q2]Pep-In-Your-Step\n[q2]Use: Restores ( 937500 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\n Pep-In-Your-Step\n If you spend at least 10 seconds drinking you will gain 167 Speed and the ability to walk on water for 10 min.\n68"}
MultiLanguageSpellData['en'][445482] = {name = "[q2]Rockslide Shake", additional_info = "2 sec cast\nReagents:\nDelver's Waterskin (5), Spongey Scramble (3), Hot Honeycomb , Bismuth (10)\nOptional Reagents:\nSecret Ingredient (#318)\n[q]Recipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\n[q2]Rockslide Shake\n[q2]Use: This isn't blended at all... (5 Min Cooldown)\n68\n[q]\"The perfect Earthen treat for a hot day in Khaz Algar.\""}
MultiLanguageSpellData['en'][445483] = {name = "[q2]Sticky Sweet Treat", additional_info = "2 sec cast\nReagents:\nSpongey Scramble (3), Hot Honeycomb , Clumped Flour (5), Coreway Dust (5)\nOptional Reagents:\nSecret Ingredient (#318)\n[q]Recipe for 10 servings. Actual number of servings will vary based on cooking skill.\nDrop:\nBroodtwister Ovi'nax\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\n[q2]Sticky Sweet Treat\n[q2]Use: Be a kid again! (5 Min Cooldown)\n68\n[q]\"Cinderbee honey from the cave networks above is a delicacy for a young nerubian.\""}
MultiLanguageSpellData['en'][445484] = {name = "[q2]Melted Candlebar", additional_info = "2 sec cast\nReagents:\nSpongey Scramble (3), Hot Honeycomb , Clumped Flour (5)\nOptional Reagents:\nSecret Ingredient (#318)\n[q]Recipe for 10 servings. Actual number of servings will vary based on cooking skill.\nVendor:\nCaptain Oathmyt\nZone:\nHallowfall\nCost:\n10\n\n[q2]Melted Candlebar\n[q2]Use: What's the harm in trying? (5 Min Cooldown)\n68\n[q]\"A perfect mixture of chewy and crunchy. You can't imagine sharing this with anyone else.\""}
