MultiLanguageSpellData['en'][446982] = {name = "[q4]Concoctor's Clutch", additional_info = "2 sec cast 2\nReagents:\nOptional Reagents:\nEmbroidery Thread (#333)\nVendor:\nKhaz Algar World Vendors\nCost:\n150\n1500\n\n[q4]Concoctor's Clutch\nBinds when picked up\nUnique\n36 Slot Bag\n[q2]Equip: Increases the chance Algari experimentations discover a new recipe by 3%.\n\n [ Equip effect requires Khaz Algar Alchemy 1 ][ Equip effect requires Khaz Algar Alchemy 1 ]68\n[q]\"Taut threads perfectly protect its inhabitants from experiments gone wrong.\""}
MultiLanguageSpellData['en'][446983] = {name = "[q4]Ignition Satchel", additional_info = "2 sec cast 2\nReagents:\nOptional Reagents:\nEmbroidery Thread (#333)\nDrop:\nAwakening the Machine\n\n[q4]Ignition Satchel\nBinds when picked up\nUnique\n36 Slot Bag\n[q2]Equip: Everburning Ignition grants an additional 20 Ingenuity, Resourcefulness, and Multicraft.\n\n [ Equip effect requires Khaz Algar Blacksmithing 1 ][ Equip effect requires Khaz Algar Blacksmithing 1 ]68\n[q]\"Imbued with Everburning Ignition, sets a Blacksmith's heart ablaze.\""}
MultiLanguageSpellData['en'][446984] = {name = "[q4]Hideshaper's Workbag", additional_info = "2 sec cast 2\nReagents:\nOptional Reagents:\nEmbroidery Thread (#333)\nVendor:\nKama\nZone:\nCity of Threads\nCost:\n150\n1500\n\n[q4]Hideshaper's Workbag\nBinds when picked up\nUnique\n36 Slot Bag\n[q2]Equip: Increases your Resourcefulness rating by 90 when crafting Leatherworking reagents.\n\n [ Equip effect requires Khaz Algar Leatherworking 1 ][ Equip effect requires Khaz Algar Leatherworking 1 ]68\n[q]\"This workbag contains numerous compartments and pouches to hold various odds, ends, and specialty items.\""}
