MultiLanguageSpellData['en'][447342] = {name = "Potion Bomb of Speed", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Potion of the Reborn Cheetah (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a burst of 10-15% movement speed (based on crafting quality) for 20 sec.\n\n Enemies caught in the blast suffer 32 fire damage, split between them.\n68"}
MultiLanguageSpellData['en'][447343] = {name = "Potion Bomb of Recovery", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Cavedweller's Delight (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases healing received by 5-10% (based on crafting quality) for 12 sec.\n\n Enemies caught in the blast suffer 32 fire damage, split between them.\n68"}
MultiLanguageSpellData['en'][447344] = {name = "Potion Bomb of Power", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Tempered Potion (3), Handful of Bismuth Bolts (2), Whimsical Wiring (2), Gyrating Gear , Safety Switch\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases their primary stat by ( 17 / 5) for 30 sec.\n\n Enemies caught in the blast suffer 32 fire damage, split between them.\n68"}
MultiLanguageSpellData['en'][447350] = {name = "[q3]Tinker: Earthen Delivery Drill", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (25), Handful of Bismuth Bolts (24), Whimsical Wiring (12), Gyrating Gear (3), Chaos Circuit (3), Entropy Enhancer (2)\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Tinker: Earthen Delivery Drill\nTinker Module\nUnique-Equipped: Earthen Delivery Drill (1)\nEarthen Delivery Drill\n\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Earthen Delivery Drill\nSummon an Earthen Delivery Drill to dig for an assortment of battleground buffs.\n\n The drill lasts for 28 sec and can only be summoned while in combat. Can only be used in unrated battlegrounds and in War Mode on Khaz Algar.\n68\n[q]\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Algari equipment.\""}
MultiLanguageSpellData['en'][447351] = {name = "[q3]Tinker: Heartseeking Health Injector", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (25), Algari Healing Potion (600), Handful of Bismuth Bolts (24), Whimsical Wiring (12), Gyrating Gear (3), Entropy Enhancer (4)\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Tinker: Heartseeking Health Injector\nTinker Module\nUnique-Equipped: Heartseeking Health Injector (1)\nHeartseeking Health Injector\n\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Heartseeking Health Injector\nInject a medicinal frostfire formula into your veins, instantly healing you for up to 32012 from a jolt of frost. To prevent sudden hypothermia, you will then burn for 30% of the amount healed.\n\n Shares a cooldown with healing potions.\n68\n[q]\"Tinker quality and engineering specialization impact success chance. With proper precautions, this tinker cannot malfunction. This warranty only applies to Algari equipment.\""}
MultiLanguageSpellData['en'][447352] = {name = "[q4]P.0.W. x2", additional_info = "2 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Bismuth Bolts (64), Whimsical Wiring (18), Gyrating Gear (12), Safety Switch (4), Chaos Circuit (2), Spark (#256) (2)\nOptional Reagents:\nSpecialization:\nEngineered Equipment - Guns\n\n[q4]P.0.W. x2\nBinds when picked up\nRanged Gun\n3,365 - 6,251 Damage Speed 3.00\n(1,603 damage per second)\n+2,129 Agility\n+9,748 Stamina\n[q2]+ 728 Random Stat 1\n[q2]+ 728 Random Stat 2\nDurability 120 / 120\n58\n[q]\"Come on, shoot faster!\""}
MultiLanguageSpellData['en'][447353] = {name = "[q2]Serrated Cogwheel", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRadiant Ruby , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Serrated Cogwheel\n\n[q2]Serrated Cogwheel\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Critical Strike.\n[q]Usable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n[q]\"Can be bought and sold on the Auction House.\""}
