MultiLanguageSpellData['en'][447356] = {name = "[q2]Adjustable Cogwheel", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nStunning Sapphire , Handful of Bismuth Bolts , Gyrating Gear , Entropy Enhancer\nOptional Reagents:\nSpecialization:\nInventing - Adjustable Cogwheel\n\n[q2]Adjustable Cogwheel\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stat of Engineering crafted goggles or bracers to Versatility.\n[q]Usable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][447357] = {name = "[q2]Recalibrated Safety Switch", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (15), Handful of Bismuth Bolts (8), Whimsical Wiring (2), Gyrating Gear (2), Safety Switch (4)\nOptional Reagents:\nDiscovery:\nComprehensibly Organized Ideas\n\n\n[q2]Recalibrated Safety Switch\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Reduces the likelihood of this device's tinker malfunctioning by 15%. Does not stack with similar specialization bonuses.\n[q]Usable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][447360] = {name = "[q2]Complicated Fuse Box", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (15), Handful of Bismuth Bolts (6), Whimsical Wiring (2), Gyrating Gear (2), Chaos Circuit , Entropy Enhancer\nOptional Reagents:\nDiscovery:\nComprehensibly Organized Ideas\n\n\n[q2]Complicated Fuse Box\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: When the tinker slotted within this device malfunctions, a fuse is flipped to prevent a hazardous outcome.\n[q]Usable with: Goggles and Bracers crafted with Khaz Algar Engineering.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][447364] = {name = "[q2]Irresistible Red Button", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (12), Whimsical Wiring (3), Gyrating Gear (4), Entropy Enhancer\nOptional Reagents:\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q2]Irresistible Red Button\nBinds when picked up\n[q2]Use: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\n Lasts for 1 hour or until activation. Must be deployed prior to combat.\n68\nRequiresKhaz Algar Engineering\n(1)"}
MultiLanguageSpellData['en'][447365] = {name = "Pausing Pylon", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (8), Whimsical Wiring (2), Gyrating Gear (2)\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q2]Use: Deploy a Pausing Pylon that will disrupt the natural metabolic processes of players standing nearby, halting the expiration of Khaz Algar Flasks, Phials, and Well Fed effects.\n\n The pylon is extremely fragile and will detonate in the presence of violence.\n68"}
MultiLanguageSpellData['en'][447367] = {name = "[q2]Algari Repair Bot 11O", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (8), Whimsical Wiring , Gyrating Gear (2), Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q2]Algari Repair Bot 11O\nBinds when picked up\n[q2]Use: Deploy a small earthen golem to allow you and fellow adventurers to repair your equipment.\n\n Lasts for 10 min.\n68\nRequiresKhaz Algar Engineering\n(1)"}
MultiLanguageSpellData['en'][447368] = {name = "[q3]Portable Profession Possibility Projector", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (10), Handful of Bismuth Bolts (12), Whimsical Wiring , Gyrating Gear (2), Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Portable Profession Possibility Projector\n[q2]Use: Summon a Possibility Projector configured to satisfy the needs of crafting tables. Only one workbench can be displayed at a time and can only be changed by the Engineer. (10 Min Cooldown)\n68\nRequiresKhaz Algar Engineering\n(1)"}
MultiLanguageSpellData['en'][447369] = {name = "[q3]Barrel of Fireworks", additional_info = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (50), Whimsical Wiring (24), Gyrating Gear (10), Chaos Circuit (8), Entropy Enhancer (3)\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Barrel of Fireworks\nToy\n[q2]Use: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\n Other players can opt-in to seeing the fireworks by attacking the barrel.\n\n Cooldown reduced during drunken goblin revelries. (1 Hour Cooldown)"}
MultiLanguageSpellData['en'][447370] = {name = "[q3]Defective Escape Pod", additional_info = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (75), Whimsical Wiring (10), Gyrating Gear (16), Safety Switch (6), Entropy Enhancer (2)\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Defective Escape Pod\nToy\n[q2]Use: Urgently seek shelter inside a defective escape pod. You won't get very far, but at least you are safe. (10 Min Cooldown)"}
MultiLanguageSpellData['en'][447371] = {name = "[q3]Filmless Camera", additional_info = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (100), Whimsical Wiring (6), Gyrating Gear (8), Safety Switch , Entropy Enhancer\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Filmless Camera\nToy\n[q2]Use: Embrace your inner photographer! (30 Sec Cooldown)"}
MultiLanguageSpellData['en'][447372] = {name = "[q3]Wormhole Generator: Khaz Algar", additional_info = "2 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Rusted Scrap (50), Handful of Bismuth Bolts (125), Whimsical Wiring (8), Gyrating Gear (16), Chaos Circuit (4), Entropy Enhancer (4)\nDiscovery:\nInventing, Prototyping, and Notes\n\n\n[q3]Wormhole Generator: Khaz Algar\nToy\n[q2]Use: Open a wormhole that allows the user to quickly travel to a random location in Khaz Algar. (30 Min Cooldown)\n68\nRequiresKhaz Algar Engineering\n(1)"}
MultiLanguageSpellData['en'][447373] = {name = "[q4]Crowd Pummeler 2-30", additional_info = "2 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nBountiful Bolts (1000), Assorted Whirligigs (200), Blinker Fluid (80), Cataclysmic Converter (50), Pummel-Proof Plating (20), Pummel Permit\n[q]The required components can be purchased from Paxton Bombshell at Opportunity Point.\n\n You may sometimes find these parts when you Pilfer Through Parts .\nDiscovery:\nComprehensibly Organized Ideas\n\n\n[q4]Crowd Pummeler 2-30\nMount[q0](Account-wide)\n[q2]Use: Teaches you how to summon the Crowd Pummeler 2-30.\n[q2]Summons and dismisses this mount.\n1 to 80 ( 80)\nRequires\n[q]\"Guaranteed to knock the teeth out from your enemies with a single punch!\"\nProfession:\nKhaz Algar Engineering"}
