MultiLanguageSpellData['en'][447867] = {name = "Kah, King of the Deeps", additional_info = "3.2 sec cast\n[q]Warped by the blood of the Old Gods, its sickly pale skin stretches over its skeletal body. Anglers across Khaz Algar speak of this fish as a messenger of doom, cursing any Angler unfortunate enough to reel it in. Staring into the eyes of this creature will only elaborate its depravity as any reflection is consumed by the abyss."}
MultiLanguageSpellData['en'][447868] = {name = "[q3]Algari Treatise on Inscription", additional_info = "3.5 sec cast\nReagents:\nLeyline Residue (2), Boundless Cipher , Apricate Ink (2)\nSpecialization:\nPursuit of Knowledge\n\n[q3]Algari Treatise on Inscription\n[q7]Binds to Warband\n[q2]Use: Study to increase your Khaz Algar Inscription Knowledge by 1. (5 Sec Cooldown)\nRequiresKhaz Algar Inscription\n(25)"}
