MultiLanguageSpellData['en'][452408] = {name = "Burning Blades", additional_info = "[q]Havoc\n Your blades burn with Fel energy, causing your Chaos Strike, Throw Glaive, and auto-attacks to deal an additional 50% damage as Fire over 6 sec.\n\nVengeance\n Your blades burn with Fel energy, causing your Soul Cleave, Throw Glaive, and auto-attacks to deal an additional 40% damage as Fire over 6 sec."}
MultiLanguageSpellData['en'][452409] = {name = "Violent Transformation", additional_info = "[q]Vengeance\n When you activate Metamorphosis, the cooldowns of your Sigil of Flame and Fel Devastation are immediately reset.\n\nHavoc\n When you activate Metamorphosis, the cooldowns of your Sigil of Flame and Immolation Aura are immediately reset."}
