MultiLanguageSpellData['en'][454426] = {name = "Delivered Doom", additional_info = "[q]Damage dealt when your Fatebound Coin flips tails is increased by 30% if there are no other enemies near the target.\n\n Each additional nearby enemy reduces this bonus by 6%."}
MultiLanguageSpellData['en'][454428] = {name = "Fateful Ending", additional_info = "[q]When your Fatebound Coin flips the same face for the seventh time in a row, keep the lucky coin to gain 7% Agility until you leave combat for 10 seconds. If you already have a lucky coin, it instead deals (420% of Attack Power) Cosmic damage to your target."}
MultiLanguageSpellData['en'][454429] = {name = "Fate Intertwined", additional_info = "[q]Outlaw\n Fate Intertwined duplicates 30% of Dispatch critical strike damage as Cosmic to 2 additional nearby enemies. If there are no additional nearby targets, duplicate 30% to the primary target instead.\n\nAssassination\n Fate Intertwined duplicates 30% of Envenom critical strike damage as Cosmic to 2 additional nearby enemies. If there are no additional nearby targets, duplicate 30% to the primary target instead."}
MultiLanguageSpellData['en'][454430] = {name = "Double Jeopardy", additional_info = "[q]Your first Fatebound Coin flip after breaking Stealth flips two coins that are guaranteed to match the same outcome."}
MultiLanguageSpellData['en'][454431] = {name = "[q4]The Severed Satchel", additional_info = "2 sec cast 2\nReagents:\nAdorning Ribbon (2), Duskweave Bolt (5), Dawnweave Bolt (5)\nOptional Reagents:\nEmbroidery Thread (#333)\nSpecialization:\nQuality Fabric (25)\n\n[q4]The Severed Satchel\nBinds when picked up\nUnique\n36 Slot Bag\n[q2]Equip: Increases the maximum yield of Khaz Algar Unraveling by 1.\n\n [ Equip effect requires Khaz Algar Tailoring 1 ][ Equip effect requires Khaz Algar Tailoring 1 ]68\n[q]\"A container spun from The Weaver's master artisans, capable of maximizing the value of cloth as elusive as Dawnweave and Duskweave.\""}
MultiLanguageSpellData['en'][454432] = {name = "Inexorable March", additional_info = "[q]You cannot be slowed below 70% of normal movement speed while your Fatebound Coin flips have an active streak of at least 2 flips matching the same face."}
MultiLanguageSpellData['en'][454433] = {name = "Death's Arrival", additional_info = "[q]Outlaw\n Grappling Hook may be used a second time within 3 sec with no cooldown, but its total cooldown is increased by 5 sec.\n\nAssassination\n Shadowstep may be used a second time within 3 sec with no cooldown, but its total cooldown is increased by 5 sec."}
MultiLanguageSpellData['en'][454434] = {name = "Inevitable End", additional_info = "[q]Outlaw\n Cold Blood now benefits the next two abilities but only applies to Dispatch. Fatebound Coins flipped by these abilities are guaranteed to match the same outcome as the last flip.\n\nAssassination\n Cold Blood now benefits the next two abilities but only applies to Envenom. Fatebound Coins flipped by these abilities are guaranteed to match the same outcome as the last flip."}
MultiLanguageSpellData['en'][454435] = {name = "Destiny Defined", additional_info = "[q]Outlaw\n Sinister Strike has 5% increased chance to strike an additional time and your Fatebound Coins flipped have an additional 5% chance to match the same face as the last flip.\n\nAssassination\n Weapon poisons have 5% increased application chance and your Fatebound Coins flipped have an additional 5% chance to match the same face as the last flip."}
