MultiLanguageSpellData['en'][456551] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nIdol of the Earthmother\n[q]Brann's spells and abilities have a chance to awaken the idol, shielding an injured player for 15 % of their missing health.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456552] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nUnbreakable Iron Idol\n[q]When any player's health falls below 40 % health during combat, the idol awakens dealing moderate Physical damage to nearby enemies and taunting them for 4 sec. Can only occur every 2 min.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456553] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nLight-Touched Idol\n[q]When any player uses a defensive ability with a cooldown of 30 sec or longer, the idol activates and heals them for ( 100 / 100)% of their maximum health every 1 sec for 10 sec.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456554] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nStreamlined Relic\n[q]While out of combat, the party's movement speed is increased by 10 %. Upon entering combat, the party's haste is increased by 5 % for 8 sec.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456555] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nIdol of Final Will\n[q]During combat, Brann designates a player to guide his shot for 4 sec before firing towards their location and dealing moderate Physical damage to the first enemy hit.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456556] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nAmorphous Relic\n[q]Upon entering combat, players gain either Massive or Miniature until combat ends.\n\n Massive\nIncreases your size by 20 %, maximum health by 5 %, and damage and healing done by 3 %.\n\n Miniature\nReduces your size by 20 %, increases movement speed by 5 %, and your haste by 3 %.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456557] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nTime Lost Relic\n[q]Brann's spell and abilities have a chance to create bursts of energy, warping the flow of time for all nearby units by 15 % for 12 sec.\n\n Casting, movement, periodic effects, cooldowns, and attack speeds are affected while time warped.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456558] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nOlden Seeker Relic\n[q]When Brann uses Gathering Tools , there is a 20 % chance to unearth a powerful artifact that grants your party a powerful Boon.\n\n Gathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection."}
MultiLanguageSpellData['en'][456559] = {name = "Adding", additional_info = "1.5 sec cast\nReagents:\nLifeless Necrotic Relic\n[q]The idol draws upon unholy energy to prevent fatal damage on players, instead healing them for an amount equal to 100 % of their maximum health and turning them Undead.\n\n While Undead, they cannot be healed, lose 14 % of their maximum health every 1 sec, and gain 6 % damage and healing done.\n\nYou already have this curio in your collection."}
